// Regenerates supabase/functions/octagon-mcp/ext_apps_bundle.ts from the MCP Apps SDK's prebuilt
// browser client (app-with-deps.js), so the widgets carry the SDK inline instead of loading it
// from a CDN at render time. The Claude docs recommend bundling for production, and it removes
// the widgets' only third-party runtime dependency.
//
// Usage:
//   npm pack @modelcontextprotocol/ext-apps@1.7.5 && tar xzf modelcontextprotocol-ext-apps-1.7.5.tgz
//   node scripts/build-ext-apps-bundle.js package/dist/src/app-with-deps.js 1.7.5
//
// The bundle is an ES module ending in `export{a as App,b as applyHostStyleVariables,...}`. That
// trailing export is rewritten to `window.McpApps={App:a,...}` so the bundle runs as a plain inline
// <script> and the widget code reads window.McpApps. "</script" is escaped so the bundle cannot
// close its own tag early.
const fs = require('fs');
const path = require('path');

const [src, version] = process.argv.slice(2);
if (!src || !version) { console.error('usage: node scripts/build-ext-apps-bundle.js <app-with-deps.js> <version>'); process.exit(1); }

let js = fs.readFileSync(src, 'utf8').trimEnd();
const at = js.lastIndexOf('export{');
if (at < 0 || !js.endsWith('};')) { console.error('unexpected bundle shape: no trailing export{...};'); process.exit(1); }
if (/(^|[;}\s])import[\s{*]/.test(js.slice(0, 2000))) { console.error('bundle has top-level imports; it is not self-contained'); process.exit(1); }

const list = js.slice(at + 'export{'.length, -2).split(',').map((s) => s.trim()).filter(Boolean);
const pairs = list.map((s) => { const m = /^([\w$]+)(?:\s+as\s+([\w$]+))?$/.exec(s); if (!m) throw new Error('cannot parse export: ' + s); return [m[2] || m[1], m[1]]; });
const want = ['App', 'applyHostStyleVariables', 'applyHostFonts', 'applyDocumentTheme'];
for (const w of want) if (!pairs.find((p) => p[0] === w)) { console.error('bundle does not export ' + w); process.exit(1); }

js = js.slice(0, at) + 'window.McpApps={' + pairs.map(([name, local]) => JSON.stringify(name) + ':' + local).join(',') + '};';
js = js.replace(/<\/script/gi, '<\\/script');

const out = path.join(__dirname, '..', 'supabase', 'functions', 'octagon-mcp', 'ext_apps_bundle.ts');
fs.writeFileSync(out,
  '// GENERATED by scripts/build-ext-apps-bundle.js — do not edit by hand.\n' +
  '// @modelcontextprotocol/ext-apps ' + version + ', app-with-deps.js, exports exposed on window.McpApps.\n' +
  'export const EXT_APPS_VERSION = ' + JSON.stringify(version) + ';\n' +
  'export const EXT_APPS_JS = ' + JSON.stringify(js) + ';\n');
console.log('wrote ' + path.relative(process.cwd(), out) + ' (' + js.length + ' chars, ' + pairs.length + ' exports)');
